using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PerniciousPipeOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/PerniciousPipeOmenData")]
public class PerniciousPipeOmenData : OmenData
{
	[Header("ShuffleMadnessOmenData Omen")]
	[SerializeField]
	private int additionalDieAmount = 1;

	[SerializeField]
	private DrawAdditionalDieOmenData drawAdditionalDieOmenData;

	[NonSerialized]
	private Func<int> drawAdditionalDieOmenAction;

	[NonSerialized]
	private Action omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		drawAdditionalDieOmenData.InitializeNoStartOfBattle(omenInstance, additionalDieAmount, ref drawAdditionalDieOmenAction);
		omenAction = delegate
		{
			omenInstance.ActivateOmenFeedback();
			ActivateOmen();
		};
		ReferenceSingleton<MiscOmensHandler>.Instance.OnShuffleDicePoolOmenActions.Add(omenAction);
	}

	public override void OmenRemoved()
	{
		drawAdditionalDieOmenData.OmenRemovedNoStartOfBattle(ref drawAdditionalDieOmenAction);
		ReferenceSingleton<MiscOmensHandler>.Instance.OnShuffleDicePoolOmenActions.Add(omenAction);
	}

	public override string OmenConvertedDescription()
	{
		return drawAdditionalDieOmenData.GetDrawAdditionalDieDescription(additionalDieAmount) + "\n" + Smart.Format(base.localizationManager.GetWheneverYouShuffleYourDicePool(), BattleAction.GetActionDescription(ActionValue).LowercaseFirst());
	}
}
